if not h:
    print("KEYS:", list(data.keys()) if isinstance(data, dict) else type(data))
    sys.exit(0)

start = h.find('entry-content')
chunk = h[start:start + 24000] if start != -1 else h
parts = re.findall(r'<(p|h2|h3|li|blockquote)[^>]*>(.*?)</\1>', chunk, re.S)
out = []
for tag, inner in parts:
    txt = re.sub(r'<[^>]+>', '', inner)
    txt = htmllib.unescape(txt).strip()
    txt = re.sub(r'\s+', ' ', txt)
    if txt:
        out.append(('# ' + txt) if tag in ('h2', 'h3') else txt)
print('\n\n'.join(out[:60]))

