fn pair_bluetooth(mac: &str) -> Result<(), String> {
    let address = parse_mac(mac.trim()).ok_or("Enter a valid Bluetooth address before pairing.")?;
    let mac = address.map(|byte| format!("{byte:02X}")).join(":");
    for action in ["pair", "trust"] {
        let output = std::process::Command::new("bluetoothctl")
            .args(["--timeout", "20", action, &mac])
            .output()
            .map_err(|error| format!("Couldn't start Bluetooth pairing: {error}"))?;
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        let already_paired = action == "pair"
            && (stdout.contains("org.bluez.Error.AlreadyExists")
                || stderr.contains("org.bluez.Error.AlreadyExists"));
        if !output.status.success() && !already_paired {
            let detail = stderr.lines().chain(stdout.lines()).filter(|line| !line.trim().is_empty()).collect::<Vec<_>>().join(" ");
            return Err(format!("Bluetooth {action} failed for {mac}. {detail}"));
        }
    }
    Ok(())
}

